        private static void RunRecoverySelfTest()
        {
            string saved = Language;
            const string message = "Die Windows-Erkennungsdienste und das Änderungsjournal wurden repariert und geprüft. Bestehende Freigaben und Dateien bleiben erhalten.";
            const string sourcePath = @"C:\Windows\WinSxS\Manifests\amd64_fdphost_31bf3856ad364e35_10.0.26100.1_none_original.manifest";
            const string detailPrefix = "Die Original-Dienstkonfiguration wird bei der Einrichtung automatisch aus Windows wiederhergestellt: ";
            WorkerResult original = new WorkerResult {
                Success = true, Message = message,
                Checks = new[] { new CheckItem { Name = "fdPHost", State = "warning", Code = "SERVICE_CONFIG_MISSING", Detail = detailPrefix + sourcePath, NextStep = "Freigabe mit aktivierter automatischer Blockaden-Reparatur einrichten." } }
            };
            string originalJson = JsonData.Serialize(original);
            try
            {
                foreach (LanguageItem item in Languages)
                {
                    Language = item.Code;
                    WorkerResult localized = TranslateResult(original);
                    if (item.Code != "de" && (localized.Message == message || localized.Checks[0].Detail == original.Checks[0].Detail || localized.Checks[0].NextStep == original.Checks[0].NextStep))
                        throw new InvalidOperationException("Recovery localization is missing: " + item.Code);
                    if (localized.Checks[0].Name != "fdPHost" || localized.Checks[0].Code != "SERVICE_CONFIG_MISSING" || localized.Checks[0].State != "warning" || !localized.Checks[0].Detail.Contains(sourcePath))
                        throw new InvalidOperationException("Recovery localization changed diagnostic data: " + item.Code);
                    string phase = TranslatePhase("Originalkonfiguration von FDResPub aus Windows prüfen …");
                    if (!phase.Contains("FDResPub") || (item.Code != "de" && phase == "Originalkonfiguration von FDResPub aus Windows prüfen …"))
                        throw new InvalidOperationException("Recovery phase localization changed a service name: " + item.Code);
                    string nativeError = T("Keine verlässlich passende originale Windows-Dienstdefinition gefunden. " + sourcePath + ": Native Fehler 87");
                    if (!nativeError.Contains(sourcePath + ": Native Fehler 87"))
                        throw new InvalidOperationException("Recovery localization changed original error details: " + item.Code);
                    if (JsonData.Serialize(original) != originalJson)
                        throw new InvalidOperationException("Recovery localization mutated the original result.");
                }
                Language = "de";
                if (TranslateResult(original).Message != message || TranslateResult(original).Checks[0].Detail != detailPrefix + sourcePath)
                    throw new InvalidOperationException("Recovery localization did not restore German source text.");
            }
            finally { Language = saved; }
        }
    }
